## Sudocode-hub Backend (Reference)

For completeness, here's how sudocode-hub would use Tier 2:

```typescript
// sudocode-hub backend (separate repo)
import { CoderClient } from 'sudopod/providers/coder/client';

// Hub API endpoint
app.post('/api/deployments', async (req, res) => {
  // Authenticate user and get their email from OAuth session
  const user = await authenticateUser(req.headers.authorization);

  // Look up user's secrets from hub database
  const userSecrets = await db.getUserSecrets(user.id);

  // Get GitHub App installation token for user
  const githubToken = await githubApp.getInstallationToken(user.id);

  // Create Tier 2 client
  const coderClient = new CoderClient({
    url: process.env.CODER_URL,
    authToken: process.env.CODER_API_TOKEN
  });

  // Ensure user exists in Coder (creates with OIDC auth if not)
  // User can then login to Coder via "Login with Google" using same email
  const coderUser = await coderClient.ensureUserWithOIDC({
    email: user.email
  });

  // Create workspace under user's account
  const workspace = await coderClient.createWorkspace({
    username: coderUser.username,
    template: req.body.template || 'sudocode-workspace-v0',
    parameters: {
      git_repo_url: `${req.body.git.owner}/${req.body.git.repo}`,
      git_branch: req.body.git.branch || 'main',
      github_token: githubToken,  // From GitHub App installation
      user_secrets: JSON.stringify(userSecrets),  // From hub database
      cpu_cores: req.body.deployment?.cpuCores || '4',
      memory_gb: req.body.deployment?.memoryGb || '16',
      disk_size_gb: req.body.deployment?.diskSizeGb || '50',
      server_port: String(req.body.server?.port || 3000),
      idle_timeout_min: String(req.body.server?.idleTimeout || 60),
      ttl_hours: String(req.body.server?.keepAliveHours || 72),
      agents: (req.body.agents || ['claude']).join(','),
      sudocode_version: req.body.sudocodeVersion || 'latest',
    }
  });

  // Return deployment info
  res.json({
    id: workspace.id,
    name: workspace.name,
    owner: coderUser.username,
    status: 'provisioning',
    urls: {
      workspace: workspace.url,
      sudocode: `${workspace.url}/port/3000`
    }
  });
});
```

