# Provider Interface Contract

## Overview

This specification defines the TypeScript `Provider` interface that all workspace providers must implement. Providers are host-side implementations that translate standardized workspace requests into backend-specific API calls (e.g., Coder, Kubernetes, etc.).

**Parent:** [[s-1u2m]] (Sudopod Provider Architecture)

## Provider Interface

```typescript
// src/types/provider.ts

/**
 * The Provider interface that all workspace providers must implement.
 * Providers run on the host side (e.g., coder-infra) and handle the
 * translation from standardized requests to backend-specific APIs.
 */
export interface Provider {
  // === Workspace Lifecycle ===

  /**
   * Create a new workspace for the given user.
   * Provider should ensure user exists (via ensureUser) before creating.
   */
  createWorkspace(req: CreateWorkspaceRequest): Promise<Workspace>;

  /**
   * Get workspace details by ID.
   */
  getWorkspace(id: string): Promise<Workspace>;

  /**
   * Permanently delete a workspace.
   */
  deleteWorkspace(id: string): Promise<void>;

  /**
   * List workspaces, optionally filtered.
   */
  listWorkspaces(filters?: ListWorkspacesFilter): Promise<Workspace[]>;

  // === Workspace State ===

  /**
   * Start a stopped workspace.
   */
  startWorkspace(id: string): Promise<void>;

  /**
   * Stop a running workspace (preserves state).
   */
  stopWorkspace(id: string): Promise<void>;

  // === User Management (Optional) ===

  /**
   * Ensure a user exists in the provider's system.
   * For OIDC providers, creates a dormant user that activates on first login.
   * Optional - not all providers need user management.
   */
  ensureUser?(req: EnsureUserRequest): Promise<User>;
}
```

## Request Types

### CreateWorkspaceRequest

```typescript
/**
 * Request to create a new workspace.
 * CLI provides repository/branch/resources.
 * Hub or self-hosted config provides identity/secrets.
 */
export interface CreateWorkspaceRequest {
  // === Provided by CLI ===

  /** Repository in "owner/repo" format */
  repository: string;

  /** Branch to clone (default: "main") */
  branch?: string;

  /** CPU cores to allocate */
  cpuCores?: number;

  /** Memory in GB */
  memoryGb?: number;

  /** Disk size in GB */
  diskSizeGb?: number;

  /** Minutes of inactivity before auto-stop */
  idleTimeoutMinutes?: number;

  /** Maximum hours before workspace is deleted */
  maxTtlHours?: number;

  // === User Identity ===

  /**
   * User identity for OIDC-based providers.
   * Injected by hub or provided via self-hosted config.
   */
  userIdentity: UserIdentity;

  // === Secrets & Tokens ===

  /** GitHub token for private repo access */
  githubToken?: string;

  /** Additional secrets to inject into workspace */
  secrets?: Record<string, string>;
}
```

### UserIdentity

```typescript
/**
 * OIDC-compatible user identity.
 * Used to create/match users in the provider's system.
 */
export interface UserIdentity {
  /**
   * OIDC email claim - primary identifier for user matching.
   * When user logs in via Google/Okta, email is matched to pre-created user.
   */
  email?: string;

  /**
   * OIDC subject identifier - IdP's internal user ID.
   * More stable than email (email can change).
   */
  sub?: string;

  /**
   * Preferred username for display purposes.
   */
  username?: string;
}
```

### EnsureUserRequest

```typescript
/**
 * Request to ensure a user exists in the provider's system.
 */
export interface EnsureUserRequest {
  /** User's email address */
  email: string;

  /** Preferred username (derived from email if not provided) */
  username?: string;

  /** Login type - always 'oidc' for our use case */
  loginType: 'oidc';

  /** Organization IDs to add user to (provider-specific) */
  organizationIds?: string[];
}
```

### ListWorkspacesFilter

```typescript
/**
 * Filters for listing workspaces.
 */
export interface ListWorkspacesFilter {
  /** Filter by owner username or email */
  owner?: string;

  /** Filter by workspace status */
  status?: WorkspaceStatus;

  /** Maximum number of results */
  limit?: number;

  /** Offset for pagination */
  offset?: number;
}
```

## Response Types

### Workspace

```typescript
/**
 * Standardized workspace representation.
 * Providers translate their backend-specific format to this.
 */
export interface Workspace {
  /** Unique workspace identifier */
  id: string;

  /** Human-readable workspace name */
  name: string;

  /** Current workspace status */
  status: WorkspaceStatus;

  /** URLs for accessing the workspace */
  urls: WorkspaceUrls;

  /** ISO 8601 timestamp of creation */
  createdAt: string;

  /** Username of workspace owner */
  owner?: string;

  /** Repository this workspace is based on */
  repository?: string;

  /** Branch checked out */
  branch?: string;
}

/**
 * URLs for accessing a workspace.
 */
export interface WorkspaceUrls {
  /** Main workspace URL (provider dashboard) */
  workspace: string;

  /** Direct IDE/VS Code URL */
  ide?: string;

  /** SSH connection string */
  ssh?: string;

  /** Terminal web URL */
  terminal?: string;
}

/**
 * Workspace lifecycle states.
 */
export type WorkspaceStatus =
  | 'pending'    // Workspace is being created
  | 'starting'   // Workspace is starting up
  | 'running'    // Workspace is ready for use
  | 'stopping'   // Workspace is shutting down
  | 'stopped'    // Workspace is stopped (can be restarted)
  | 'failed'     // Workspace creation/operation failed
  | 'deleting';  // Workspace is being deleted
```

### User

```typescript
/**
 * User representation returned by ensureUser.
 */
export interface User {
  /** Unique user identifier */
  id: string;

  /** Username */
  username: string;

  /** User's email address */
  email: string;

  /** User status in the provider's system */
  status: UserStatus;

  /** ISO 8601 timestamp of creation */
  createdAt: string;
}

/**
 * User status in the provider's system.
 */
export type UserStatus =
  | 'active'    // User has logged in at least once
  | 'dormant'   // User created via API, hasn't logged in yet
  | 'suspended'; // User is suspended
```

## Error Types

```typescript
/**
 * Base error for provider operations.
 */
export class ProviderError extends Error {
  constructor(
    message: string,
    public code: ProviderErrorCode,
    public statusCode: number = 500
  ) {
    super(message);
    this.name = 'ProviderError';
  }
}

export type ProviderErrorCode =
  | 'WORKSPACE_NOT_FOUND'
  | 'WORKSPACE_ALREADY_EXISTS'
  | 'USER_NOT_FOUND'
  | 'USER_ALREADY_EXISTS'
  | 'INVALID_REQUEST'
  | 'QUOTA_EXCEEDED'
  | 'PROVIDER_UNAVAILABLE'
  | 'AUTHENTICATION_FAILED'
  | 'AUTHORIZATION_FAILED'
  | 'INTERNAL_ERROR';

/**
 * Workspace not found error.
 */
export class WorkspaceNotFoundError extends ProviderError {
  constructor(id: string) {
    super(`Workspace not found: ${id}`, 'WORKSPACE_NOT_FOUND', 404);
  }
}

/**
 * User not found error.
 */
export class UserNotFoundError extends ProviderError {
  constructor(identifier: string) {
    super(`User not found: ${identifier}`, 'USER_NOT_FOUND', 404);
  }
}

/**
 * User already exists error.
 */
export class UserAlreadyExistsError extends ProviderError {
  constructor(email: string) {
    super(`User already exists: ${email}`, 'USER_ALREADY_EXISTS', 409);
  }
}
