## Integration with Server

CoderProvider is instantiated in the main entry point and passed to `createServer()`:

```typescript
// coder-infra/src/main.ts

import { createServer } from 'sudopod';
import { CoderProvider } from './provider';
import { bootstrapCoder } from './bootstrap';

async function main() {
  const coderUrl = process.env.CODER_URL || 'http://coder:7080';

  // Bootstrap admin credentials (see s-TODO deployment spec)
  const credentials = await bootstrapCoder(coderUrl);

  // Create provider
  const provider = new CoderProvider({
    coderUrl,
    adminToken: credentials.adminToken,
    templateName: process.env.CODER_TEMPLATE || 'sudocode-workspace',
  });

  // Create and start server
  const server = createServer(provider, {
    apiKeys: process.env.SUDOPOD_API_KEYS?.split(',') ?? [],
  });

  const port = parseInt(process.env.PORT || '8080', 10);
  server.listen(port, () => {
    console.log(`sudopod-api listening on :${port}`);
  });
}

main().catch((error) => {
  console.error('Failed to start server:', error);
  process.exit(1);
});
```

