# SudopodClient Implementation

## Overview

This specification defines the `SudopodClient` class - a typed HTTP client for calling sudopod provider hosts. This client is the shared foundation used by both sudocode-hub and the SelfHostedConnector.

**Parent:** [[s-1u2m]] (Sudopod Provider Architecture)
**Depends on:** [[s-7gqg]] (Provider Interface Contract) - for types
**Used by:** HubConnector, SelfHostedConnector, sudocode-hub

## Purpose

The `SudopodClient` provides:
- Type-safe HTTP calls to any sudopod provider host
- Bearer token authentication
- Consistent error handling and retries
- Single implementation shared by hub and self-hosted modes

## Client Configuration

```typescript
// src/client/index.ts

export interface SudopodClientConfig {
  /**
   * Base URL of the provider host
   * Example: "https://coder.mycompany.com:8080"
   */
  providerUrl: string;

  /**
   * API key for Bearer token authentication
   */
  apiKey: string;

  /**
   * Optional request timeout in milliseconds
   * Default: 30000 (30 seconds)
   */
  timeout?: number;

  /**
   * Optional number of retries for failed requests
   * Default: 3
   */
  retries?: number;

  /**
   * Optional base path prefix (if server uses one)
   * Example: "/api/v1"
   */
  basePath?: string;
}
```

## Client Implementation

```typescript
// src/client/index.ts

import type {
  CreateWorkspaceRequest,
  Workspace,
  ListFilters,
  User,
  EnsureUserRequest,
  ProviderError,
} from '../types';

export class SudopodClient {
  private baseUrl: string;
  private apiKey: string;
  private timeout: number;
  private retries: number;

  constructor(config: SudopodClientConfig) {
    // Normalize URL (remove trailing slash)
    const base = config.providerUrl.replace(/\/$/, '');
    const path = config.basePath ? `/${config.basePath.replace(/^\/|\/$/g, '')}` : '';
    this.baseUrl = `${base}${path}`;
    this.apiKey = config.apiKey;
    this.timeout = config.timeout ?? 30000;
    this.retries = config.retries ?? 3;
  }

  // === Workspace Methods ===

  async createWorkspace(req: CreateWorkspaceRequest): Promise<Workspace> {
    return this.request<Workspace>('POST', '/workspaces', req);
  }

  async getWorkspace(id: string): Promise<Workspace> {
    return this.request<Workspace>('GET', `/workspaces/${encodeURIComponent(id)}`);
  }

  async deleteWorkspace(id: string): Promise<void> {
    await this.request<void>('DELETE', `/workspaces/${encodeURIComponent(id)}`);
  }

  async listWorkspaces(filters?: ListFilters): Promise<Workspace[]> {
    const params = new URLSearchParams();
    if (filters?.owner) params.set('owner', filters.owner);
    if (filters?.status) params.set('status', filters.status);
    if (filters?.limit) params.set('limit', String(filters.limit));
    if (filters?.offset) params.set('offset', String(filters.offset));

    const query = params.toString();
    const path = query ? `/workspaces?${query}` : '/workspaces';
    return this.request<Workspace[]>('GET', path);
  }

  async startWorkspace(id: string): Promise<void> {
    await this.request<void>('POST', `/workspaces/${encodeURIComponent(id)}/start`);
  }

  async stopWorkspace(id: string): Promise<void> {
    await this.request<void>('POST', `/workspaces/${encodeURIComponent(id)}/stop`);
  }

  // === User Methods ===

  async ensureUser(req: EnsureUserRequest): Promise<User> {
    return this.request<User>('POST', '/users', req);
  }

  // === Health Check ===

  async health(): Promise<{ ok: boolean; timestamp: string }> {
    return this.request<{ ok: boolean; timestamp: string }>('GET', '/health');
  }

  // === Internal Request Handler ===

  private async request<T>(
    method: string,
    path: string,
    body?: unknown
  ): Promise<T> {
    const url = `${this.baseUrl}${path}`;

    let lastError: Error | undefined;

    for (let attempt = 0; attempt <= this.retries; attempt++) {
      try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), this.timeout);

        const response = await fetch(url, {
          method,
          headers: {
            'Authorization': `Bearer ${this.apiKey}`,
            'Content-Type': 'application/json',
          },
          body: body ? JSON.stringify(body) : undefined,
          signal: controller.signal,
        });

        clearTimeout(timeoutId);

        // Handle no-content responses
        if (response.status === 204) {
          return undefined as T;
        }

        // Parse response body
        const data = await response.json();

        // Handle errors
        if (!response.ok) {
          throw new SudopodClientError(
            data.error || `Request failed with status ${response.status}`,
            data.code || 'UNKNOWN_ERROR',
            response.status
          );
        }

        return data as T;

      } catch (error: any) {
        lastError = error;

        // Don't retry on client errors (4xx)
        if (error instanceof SudopodClientError && error.statusCode < 500) {
          throw error;
        }

        // Don't retry on abort (timeout)
        if (error.name === 'AbortError') {
          throw new SudopodClientError(
            'Request timed out',
            'TIMEOUT',
            408
          );
        }

        // Retry on network errors and 5xx
        if (attempt < this.retries) {
          // Exponential backoff: 100ms, 200ms, 400ms...
          await this.sleep(100 * Math.pow(2, attempt));
          continue;
        }
      }
    }

    throw lastError || new Error('Request failed');
  }

  private sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}
