// sudocode-hub/src/providers.ts

import { SudopodClient } from 'sudopod';

app.post('/api/providers/:provider/workspaces', async (req, res) => {
  const providerConfig = await db.getProviderConfig(req.params.provider);

  const client = new SudopodClient({
    providerUrl: providerConfig.hostUrl,
    apiKey: providerConfig.apiKey,
