        })
      );
    });

    it('throws SudopodClientError on 400 response', async () => {
      fetchSpy.mockResolvedValue(new Response(
        JSON.stringify({ error: 'Invalid request', code: 'INVALID_REQUEST' }),
        { status: 400 }
      ));

      const client = new SudopodClient({
        providerUrl: 'https://example.com',
        apiKey: 'test-key',
      });

      await expect(client.createWorkspace({
        repository: 'invalid',
        userIdentity: { email: 'user@test.com' },
      })).rejects.toThrow(SudopodClientError);
    });
  });

  describe('getWorkspace', () => {
    it('URL-encodes workspace ID', async () => {
      fetchSpy.mockResolvedValue(new Response(
        JSON.stringify({ id: 'ws/123', name: 'test', status: 'running' }),
        { status: 200 }
      ));

      const client = new SudopodClient({
        providerUrl: 'https://example.com',
        apiKey: 'test-key',
      });

      await client.getWorkspace('ws/123');

      expect(fetchSpy).toHaveBeenCalledWith(
        'https://example.com/workspaces/ws%2F123',
        expect.anything()
      );
    });
  });

  describe('deleteWorkspace', () => {
    it('handles 204 No Content response', async () => {
      fetchSpy.mockResolvedValue(new Response(null, { status: 204 }));

      const client = new SudopodClient({
        providerUrl: 'https://example.com',
        apiKey: 'test-key',
      });

      await expect(client.deleteWorkspace('ws-123')).resolves.toBeUndefined();
    });
  });

  describe('listWorkspaces', () => {
    it('includes query parameters from filters', async () => {
      fetchSpy.mockResolvedValue(new Response(
        JSON.stringify([]),
        { status: 200 }
      ));

      const client = new SudopodClient({
        providerUrl: 'https://example.com',
        apiKey: 'test-key',
      });

      await client.listWorkspaces({
        owner: 'user@test.com',
        status: 'running',
        limit: 10,
      });

      expect(fetchSpy).toHaveBeenCalledWith(
        expect.stringContaining('owner=user%40test.com'),
        expect.anything()
      );
      expect(fetchSpy).toHaveBeenCalledWith(
        expect.stringContaining('status=running'),
        expect.anything()
      );
    });
  });

  describe('retry behavior', () => {
    it('retries on 500 errors', async () => {
      fetchSpy
        .mockResolvedValueOnce(new Response(
          JSON.stringify({ error: 'Server error' }),
          { status: 500 }
        ))
        .mockResolvedValueOnce(new Response(
          JSON.stringify({ id: 'ws-123', name: 'test', status: 'running' }),
          { status: 200 }
        ));

      const client = new SudopodClient({
        providerUrl: 'https://example.com',
        apiKey: 'test-key',
        retries: 3,
      });

      const result = await client.getWorkspace('ws-123');

      expect(fetchSpy).toHaveBeenCalledTimes(2);
      expect(result.id).toBe('ws-123');
    });

    it('does not retry on 400 errors', async () => {
      fetchSpy.mockResolvedValue(new Response(
        JSON.stringify({ error: 'Bad request', code: 'INVALID_REQUEST' }),
        { status: 400 }
      ));

      const client = new SudopodClient({
        providerUrl: 'https://example.com',
        apiKey: 'test-key',
        retries: 3,
      });

      await expect(client.getWorkspace('ws-123')).rejects.toThrow();
      expect(fetchSpy).toHaveBeenCalledTimes(1); // No retries
    });

    it('throws after max retries exceeded', async () => {
      fetchSpy.mockResolvedValue(new Response(
        JSON.stringify({ error: 'Server error' }),
        { status: 500 }
      ));

      const client = new SudopodClient({
        providerUrl: 'https://example.com',
        apiKey: 'test-key',
        retries: 2,
      });

      await expect(client.getWorkspace('ws-123')).rejects.toThrow();
      expect(fetchSpy).toHaveBeenCalledTimes(3); // Initial + 2 retries
    });
  });

  describe('timeout handling', () => {
    it('throws on timeout', async () => {
      fetchSpy.mockImplementation(() => new Promise(resolve => {
        setTimeout(() => resolve(new Response('{}', { status: 200 })), 5000);
      }));

      const client = new SudopodClient({
        providerUrl: 'https://example.com',
        apiKey: 'test-key',
        timeout: 100, // 100ms timeout
      });

      await expect(client.health()).rejects.toThrow('timed out');
    });
  });

  describe('health', () => {
    it('returns health check response', async () => {
      const timestamp = new Date().toISOString();
      fetchSpy.mockResolvedValue(new Response(
        JSON.stringify({ ok: true, timestamp }),
        { status: 200 }
      ));

      const client = new SudopodClient({
        providerUrl: 'https://example.com',
        apiKey: 'test-key',
      });

      const result = await client.health();
      expect(result.ok).toBe(true);
      expect(result.timestamp).toBe(timestamp);
    });
  });
});
