## CLI Usage Example

```typescript
// sudocode CLI

import { createConnector } from 'sudopod';

// Load config
const config = loadConnectorConfig('hub-coder');

// Create connector
const connector = createConnector(config);

// Create workspace (no secrets needed - hub injects them)
const workspace = await connector.createWorkspace({
  repository: 'owner/repo',
  branch: 'main',
  cpuCores: 4,
  memoryGb: 8,
});

