### Codespaces Provider

```typescript
class CodespacesProvider implements Provider {
  readonly type = 'codespaces';
  readonly name = 'GitHub Codespaces';

  async create(options: CreateOptions): Promise<Workspace> {
    // 1. Map resources to machine size (best effort)
    // 2. Run: gh codespace create --repo owner/repo --branch branch --machine size
    //    --retention-period $retentionDays
    // 3. Wait for status "Available"
    // 4. Apply SetupConfig (one-time):
    //    - Install agents
    //    - Inject secrets
    //    - Configure models
    //    - Run setup script
    // 5. Apply RuntimeConfig:
    //    - Start sudocode server on configured port
    //    - Start keepalive daemon
    //    - Setup port forwarding
    // 6. Return workspace (with sudocode + ide URLs)
  }

  async resume(workspaceId?: string, options?: ResumeOptions): Promise<Workspace> {
    // 1. If no workspaceId, list() and pick most recent
    // 2. Check workspace status
    // 3. If stopped → start it, wait for "Available"
    // 4. Apply RuntimeConfig:
    //    - Ensure sudocode server running
    //    - Ensure keepalive daemon running (bumps deadline)
    //    - Ensure port forwarding setup
    // 5. Return workspace (with sudocode + ide URLs)
  }

  // Keepalive uses SSH ping (activity detection)
  private getBumpCommand(workspaceId: string): string {
    return `gh codespace ssh -c ${workspaceId} -- echo keepalive`;
  }
}
