## API Endpoints

### create()

```typescript
async create(options: CreateOptions): Promise<Workspace> {
  // 1. Get current user OR target user if userEmail specified
  const me = await this.apiRequest<CoderUser>('GET', '/api/v2/users/me');

  // 2. Resolve target user for workspace ownership
  let targetUser = me;
  if (this.userEmail) {
    // Hub flow or admin creating for teammate
    targetUser = await this.apiRequest<CoderUser>(
      'GET', 
      `/api/v2/users/${encodeURIComponent(this.userEmail)}`
    );
  }

  // 3. Resolve template
  const templateName = options.providerParams?.template as string ?? 'default';
  const template = await this.apiRequest<CoderTemplate>(
    'GET', 
    `/api/v2/organizations/${me.organization_ids[0]}/templates/${templateName}`
  );

  // 4. Get template version for parameters
  const version = await this.apiRequest<CoderTemplateVersion>(
    'GET',
    `/api/v2/templateversions/${template.active_version_id}`
  );

  // 5. Build rich parameters from resources + providerParams
  const richParameters = this.buildParameters(options, version);

  // 6. Create workspace for target user
  const workspace = await this.apiRequest<CoderWorkspace>(
    'POST',
    `/api/v2/organizations/${me.organization_ids[0]}/members/${targetUser.username}/workspaces`,
    {
      name: options.name,
      template_id: template.id,
      rich_parameter_values: richParameters,
      // Set deadline based on retentionDays
      ttl_ms: options.retentionDays * 24 * 60 * 60 * 1000,
    }
  );

  // 7. Wait for workspace to be running
  await this.waitForStatus(workspace.id, 'running');

  // 8. Configure coder CLI to use this instance
  await this.configureCli();

  // 9. Apply setup config
  if (options.setup) {
    await this.applySetupConfig(workspace.name, options.setup);
  }

  // 10. Apply runtime config
  await this.applyRuntimeConfig(workspace.name, options.runtime ?? {});

  // 11. Return workspace
  return this.get(workspace.id);
}
```

### resume()

```typescript
async resume(workspaceId?: string, options?: ResumeOptions): Promise<Workspace> {
  // 1. If no workspaceId, get most recent
  if (!workspaceId) {
    const workspaces = await this.list();
    if (workspaces.length === 0) {
      throw new Error('No workspaces found');
    }
    // Sort by createdAt descending
    workspaces.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());
    workspaceId = workspaces[0].id;
  }

  // 2. Get workspace
  const workspace = await this.apiRequest<CoderWorkspace>(
    'GET',
    `/api/v2/workspaces/${workspaceId}`
  );

  // 3. If stopped, start it
  if (workspace.latest_build.status === 'stopped') {
    await this.apiRequest(
      'POST',
      `/api/v2/workspaces/${workspaceId}/builds`,
      { transition: 'start' }
    );
    await this.waitForStatus(workspaceId, 'running');
  }

  // 4. Ensure CLI configured
  await this.configureCli();

  // 5. Apply runtime config (NOT setup - that was done during create)
  await this.applyRuntimeConfig(workspace.name, options?.runtime ?? {});

  // 6. Return updated workspace
  return this.get(workspaceId);
}
```

