### get()

```typescript
async get(workspaceId: string): Promise<Workspace> {
  const workspace = await this.apiRequest<CoderWorkspace>(
    'GET',
    `/api/v2/workspaces/${workspaceId}`
  );

  // Get agent for URLs
  const agents = workspace.latest_build.resources
    .flatMap(r => r.agents ?? [])
    .filter(a => a.status === 'connected');

  const agent = agents[0];

  return this.mapToWorkspace(workspace, agent);
}
```

### list()

```typescript
async list(filters?: ListWorkspacesOptions): Promise<Workspace[]> {
  const me = await this.apiRequest<CoderUser>('GET', '/api/v2/users/me');

  let query = `owner:${me.username}`;
  if (filters?.status?.length) {
    // Coder uses different status names
    const coderStatuses = filters.status.map(s => this.mapStatusToCoderQuery(s));
    query += ` status:${coderStatuses.join(',')}`;
  }

  const response = await this.apiRequest<{ workspaces: CoderWorkspace[] }>(
    'GET',
    `/api/v2/workspaces?q=${encodeURIComponent(query)}&limit=${filters?.limit ?? 50}`
  );

  return response.workspaces
    .filter(w => {
      if (filters?.owner && !w.owner_name.includes(filters.owner)) return false;
      if (filters?.repo) {
        // Check if any parameter matches repo (template-dependent)
        const repoParam = w.latest_build.resources
          .flatMap(r => r.metadata ?? [])
          .find(m => m.key === 'repository');
        if (repoParam && !repoParam.value.includes(filters.repo)) return false;
      }
      return true;
    })
    .map(w => this.mapToWorkspace(w));
}
```

