### Exec (internal)

```typescript
private async exec(workspaceName: string, command: string, options?: { background?: boolean }): Promise<ExecResult> {
  const fullCommand = options?.background
    ? `coder ssh ${workspaceName} -- bash -l -c "nohup ${command} > /dev/null 2>&1 &"`
    : `coder ssh ${workspaceName} -- bash -l -c "${command.replace(/"/g, '\\"')}"`;

  try {
    const { stdout, stderr } = await execAsync(fullCommand, { timeout: 60000 });
    return { exitCode: 0, stdout, stderr };
  } catch (error: any) {
    return { 
      exitCode: error.code ?? 1, 
      stdout: error.stdout ?? '', 
      stderr: error.stderr ?? error.message 
    };
  }
}
```

