## Setup Flow (create only)

Same as Codespaces - runs once during create:

```typescript
private async applySetupConfig(workspaceName: string, setup: SetupConfig): Promise<void> {
  // 1. Install agents
  if (setup.agents?.install?.length) {
    for (const agent of setup.agents.install) {
      await this.exec(workspaceName, `sudocode agent install ${agent}`);
    }
  }

  // 2. Inject secrets
  if (setup.secrets) {
    await this.exec(workspaceName, 'mkdir -p ~/.sudocode/secrets');
    for (const [key, value] of Object.entries(setup.secrets)) {
      const encoded = Buffer.from(value).toString('base64');
      await this.exec(workspaceName, `echo "${encoded}" | base64 -d > ~/.sudocode/secrets/${key}`);
    }
  }

  // 3. Configure models
  if (setup.models) {
    const config = JSON.stringify(setup.models);
    const encoded = Buffer.from(config).toString('base64');
    await this.exec(workspaceName, `echo "${encoded}" | base64 -d > ~/.sudocode/models.json`);
  }

  // 4. Run setup script
  if (setup.setupScript) {
    await this.exec(workspaceName, setup.setupScript);
  }
}
```

