## Runtime Flow (create and resume)

```typescript
private async applyRuntimeConfig(workspaceName: string, runtime: RuntimeConfig): Promise<void> {
  const port = runtime.port ?? 3000;

  // 1. Check if sudocode server is running
  const result = await this.exec(workspaceName, `pgrep -f "sudocode.*--port ${port}" || true`);

  if (!result.stdout.trim()) {
    // 2. Start sudocode server
    await this.exec(workspaceName, `sudocode serve --port ${port}`, { background: true });

    // 3. Wait for server to be ready
    await this.waitForPort(workspaceName, port);
  }

  // 4. Ensure keepalive daemon is running
  await this.ensureKeepaliveDaemon(workspaceName, runtime);

  // 5. Port forwarding handled by Coder's built-in port forward
  // (accessible via workspace URL)
}
```

