## Keepalive Daemon

**Key difference from Codespaces**: Uses `coder bump` to explicitly extend the workspace deadline.

```typescript
private async ensureKeepaliveDaemon(workspaceName: string, runtime: RuntimeConfig): Promise<void> {
  const port = runtime.port ?? 3000;
  const idleTimeout = runtime.lifecycle?.idleTimeoutMinutes ?? 60;

  // Check if daemon already running
  const check = await this.exec(workspaceName, 'pgrep -f "sudocode-keepalive" || true');
  if (check.stdout.trim()) return;

  // Generate and start daemon script
  const script = this.generateKeepaliveScript(port, idleTimeout);
  const encoded = Buffer.from(script).toString('base64');

  await this.exec(workspaceName, `echo "${encoded}" | base64 -d > /tmp/sudocode-keepalive.sh`);
  await this.exec(workspaceName, 'chmod +x /tmp/sudocode-keepalive.sh');
  await this.exec(workspaceName, '/tmp/sudocode-keepalive.sh', { background: true });
}

private generateKeepaliveScript(port: number, idleTimeoutMinutes: number): string {
  return `#!/bin/bash
# Sudocode keepalive daemon for Coder
# Uses 'coder bump' to extend workspace deadline
LOG_FILE="/tmp/sudocode-${port}.log"
IDLE_TIMEOUT_SECONDS=$((${idleTimeoutMinutes} * 60))
CHECK_INTERVAL=30
BUMP_HOURS=2

while true; do
  sleep $CHECK_INTERVAL

  # Check log file mtime for recent activity
  if [ -f "$LOG_FILE" ]; then
    LAST_MODIFIED=$(stat -c %Y "$LOG_FILE" 2>/dev/null || stat -f %m "$LOG_FILE")
    NOW=$(date +%s)
    IDLE_SECONDS=$((NOW - LAST_MODIFIED))

    if [ $IDLE_SECONDS -lt $IDLE_TIMEOUT_SECONDS ]; then
      # Active - bump workspace deadline
      # $CODER_WORKSPACE_NAME is set automatically by Coder agent
      coder bump $CODER_WORKSPACE_NAME ${BUMP_HOURS}h 2>/dev/null || true
    fi
  fi
done
`;
}
```

