## Workspace Mapping

```typescript
private mapToWorkspace(ws: CoderWorkspace, agent?: CoderAgent): Workspace {
  // Find sudocode port in agent apps or default to 3000
  const sudocodeApp = agent?.apps?.find(a => a.slug === 'sudocode');
  const sudocodeUrl = sudocodeApp?.url ?? (agent ? `https://${agent.name}--sudocode.${this.getProxyDomain()}` : '');

  // IDE URL (VS Code in browser)
  const vscodeApp = agent?.apps?.find(a => a.slug === 'code-server' || a.slug === 'vscode');
  const ideUrl = vscodeApp?.url ?? (agent ? `https://${agent.name}--code.${this.getProxyDomain()}` : '');

  return {
    id: ws.id,
    name: ws.name,
    provider: 'coder',
    status: this.mapStatus(ws.latest_build.status),
    repository: {
      owner: this.extractRepoOwner(ws),
      repo: this.extractRepoName(ws),
    },
    createdAt: new Date(ws.created_at),
    lastActivityAt: ws.last_used_at ? new Date(ws.last_used_at) : undefined,
    urls: {
      sudocode: sudocodeUrl,
      ide: ideUrl,
      dashboard: `${this.url}/@${ws.owner_name}/${ws.name}`,
    },
    ssh: agent ? {
      command: `coder ssh ${ws.name}`,
    } : undefined,
  };
}

private mapStatus(status: string): WorkspaceStatus {
  switch (status) {
    case 'running': return 'running';
    case 'starting': return 'starting';
    case 'stopped': return 'stopped';
    case 'stopping': return 'stopping';
    case 'pending': return 'creating';
    case 'deleting': return 'deleting';
    case 'deleted': return 'deleting';
    case 'failed': return 'failed';
    case 'canceled': return 'failed';
    default: return 'failed';
  }
}

private getProxyDomain(): string {
  // Extract domain from Coder URL for wildcard proxy
  const url = new URL(this.url);
  return url.hostname;
}
```

