## Template Parameters

Map CreateOptions to Coder template parameters:

```typescript
private buildParameters(options: CreateOptions, version: CoderTemplateVersion): RichParameterValue[] {
  const params: RichParameterValue[] = [];

  // Map resources to common parameter names (template-dependent)
  if (options.resources?.cpuCores) {
    params.push({ name: 'cpu', value: String(options.resources.cpuCores) });
  }
  if (options.resources?.memoryGb) {
    params.push({ name: 'memory', value: String(options.resources.memoryGb) });
  }
  if (options.resources?.diskSizeGb) {
    params.push({ name: 'disk_size', value: String(options.resources.diskSizeGb) });
  }

  // Repository
  params.push({ 
    name: 'repository', 
    value: `${options.repository.owner}/${options.repository.repo}` 
  });
  if (options.repository.branch) {
    params.push({ name: 'branch', value: options.repository.branch });
  }

  // Pass through provider params
  if (options.providerParams) {
    for (const [key, value] of Object.entries(options.providerParams)) {
      if (key !== 'template') { // template is handled separately
        params.push({ name: key, value: String(value) });
      }
    }
  }

  // Filter to only parameters that exist in template
  const validParamNames = new Set(version.job.rich_parameter_values?.map(p => p.name) ?? []);
  return params.filter(p => validParamNames.has(p.name));
}
```

