### Test Lifecycle

```typescript
describe('CoderProvider', () => {
  let provider: CoderProvider;
  let testWorkspaceId: string | undefined;

  beforeAll(() => {
    provider = new CoderProvider(
      process.env.CODER_URL!,
      process.env.CODER_TOKEN!
    );
  });

  afterAll(async () => {
    // Cleanup: delete test workspace if created
    if (testWorkspaceId) {
      await provider.delete(testWorkspaceId);
    }
  });

  it('should create workspace', async () => {
    const workspace = await provider.create({
      name: `test-${Date.now()}`,
      repository: { 
        owner: 'sudocode-ai', 
        repo: 'cluster-server' 
      },
      retentionDays: 1,
      providerParams: {
        machine_type: 't4g.small', // Small for tests
      },
    });

    testWorkspaceId = workspace.id;
    expect(workspace.status).toBe('running');
  });

  it('should stop workspace', async () => {
    await provider.stop(testWorkspaceId!);
    const workspace = await provider.get(testWorkspaceId!);
    expect(workspace.status).toBe('stopped');
  });

  it('should resume workspace', async () => {
    const workspace = await provider.resume(testWorkspaceId!);
    expect(workspace.status).toBe('running');
  });
});
```

