## Setup Flow (create only)

After codespace is running:

```typescript
async applySetupConfig(name: string, setup: SetupConfig): Promise<void> {
  // 1. Install agents
  if (setup.agents?.install?.length) {
    for (const agent of setup.agents.install) {
      await this.exec(name, `sudocode agent install ${agent}`);
    }
  }

  // 2. Inject secrets
  if (setup.secrets) {
    await this.exec(name, 'mkdir -p ~/.sudocode/secrets');
    for (const [key, value] of Object.entries(setup.secrets)) {
      // Use base64 to handle special characters
      const encoded = Buffer.from(value).toString('base64');
      await this.exec(name, `echo "${encoded}" | base64 -d > ~/.sudocode/secrets/${key}`);
    }
  }

  // 3. Configure models
  if (setup.models) {
    const config = JSON.stringify(setup.models);
    const encoded = Buffer.from(config).toString('base64');
    await this.exec(name, `echo "${encoded}" | base64 -d > ~/.sudocode/models.json`);
  }

  // 4. Run setup script
  if (setup.setupScript) {
    await this.exec(name, setup.setupScript);
  }
}
```

