## Keepalive Daemon

Codespaces detects SSH activity as "active usage". The daemon periodically makes SSH connections to keep the codespace alive.

```typescript
async ensureKeepaliveDaemon(name: string, runtime: RuntimeConfig): Promise<void> {
  const port = runtime.port ?? 3000;
  const idleTimeout = runtime.lifecycle?.idleTimeoutMinutes ?? 60;

  // Check if daemon already running
  const check = await this.exec(name, 'pgrep -f "sudocode-keepalive" || true');
  if (check.stdout.trim()) return; // Already running

  // Generate and start daemon script
  const script = this.generateKeepaliveScript(name, port, idleTimeout);
  const encoded = Buffer.from(script).toString('base64');

  await this.exec(name, `echo "${encoded}" | base64 -d > /tmp/sudocode-keepalive.sh`);
  await this.exec(name, 'chmod +x /tmp/sudocode-keepalive.sh');
  await this.exec(name, 'nohup /tmp/sudocode-keepalive.sh > /tmp/sudocode-keepalive.log 2>&1 &');
}

generateKeepaliveScript(name: string, port: number, idleTimeoutMinutes: number): string {
  return `#!/bin/bash
# Sudocode keepalive daemon for Codespaces
LOG_FILE="/tmp/sudocode-${port}.log"
IDLE_TIMEOUT_SECONDS=$((${idleTimeoutMinutes} * 60))
CHECK_INTERVAL=30

while true; do
  sleep $CHECK_INTERVAL

  # Check log file mtime for recent activity
  if [ -f "$LOG_FILE" ]; then
    LAST_MODIFIED=$(stat -c %Y "$LOG_FILE" 2>/dev/null || stat -f %m "$LOG_FILE")
    NOW=$(date +%s)
    IDLE_SECONDS=$((NOW - LAST_MODIFIED))

    if [ $IDLE_SECONDS -lt $IDLE_TIMEOUT_SECONDS ]; then
      # Active - ping to keep alive (SSH activity counts for Codespaces)
      gh codespace ssh -c ${name} -- echo "keepalive" > /dev/null 2>&1
    fi
  fi
done
`;
}
```

