## Workspace Mapping

Map `gh codespace list` JSON to Workspace type:

```typescript
function mapToWorkspace(cs: GhCodespace, urls?: { sudocode?: string }): Workspace {
  return {
    id: cs.name,
    name: cs.name,
    provider: 'codespaces',
    status: mapStatus(cs.state),
    repository: {
      owner: cs.repository.split('/')[0],
      repo: cs.repository.split('/')[1],
    },
    createdAt: new Date(cs.createdAt),
    lastActivityAt: cs.lastUsedAt ? new Date(cs.lastUsedAt) : undefined,
    urls: {
      sudocode: urls?.sudocode ?? '',
      ide: `https://${cs.name}.github.dev`,
      dashboard: `https://github.com/codespaces/${cs.name}`,
    },
    ssh: {
      command: `gh codespace ssh -c ${cs.name}`,
    },
  };
}

function mapStatus(state: string): WorkspaceStatus {
  switch (state) {
    case 'Available': return 'running';
    case 'Starting': return 'starting';
    case 'Shutdown': return 'stopped';
    case 'ShuttingDown': return 'stopping';
    case 'Provisioning': return 'creating';
    case 'Deleted': return 'deleting';
    default: return 'failed';
  }
}
```

